mapper.update:
UPDATE RECEPTIONIST_REGISTER
SET RECEIPT_STATUS = '보류',
HOLD_REASON = #{holdReason}
WHERE MEDICAL_NUMBER = #{medicalNumber}

UPDATE RECEPTIONIST_REGISTER
SET RECEIPT_STATUS = '접수완료'
WHERE MEDICAL_NUMBER = #{medicalNumber}

UPDATE RECEPTIONIST_REGISTER
SET RECEIPT_STATUS = '호출중'
WHERE MEDICAL_NUMBER = (
SELECT MEDICAL_NUMBER FROM (
SELECT MEDICAL_NUMBER
FROM RECEPTIONIST_REGISTER
WHERE SPACE_NUMBER = #{spaceNumber}
AND RECEIPT_STATUS = '접수완료'
AND MEDICAL_NUMBER != #{excludeMedicalNumber}
ORDER BY RECEIPT_DATE ASC, MEDICAL_NUMBER ASC
) WHERE ROWNUM = 1
)
AND NOT EXISTS (
SELECT 1 FROM RECEPTIONIST_REGISTER
WHERE SPACE_NUMBER = #{spaceNumber}
AND RECEIPT_STATUS IN ('호출중', '진료중')
)
